# This is merely used to parse benchmark logs
# USAGE: python parse_benchmarks.py
#           /path/to/run_benchmarks.sh/output.txt
#           -o /dir/to/output

import argparse
import csv
import re
import json
import math
from pathlib import Path

CONFIG_RE = re.compile(
    r"NUM_THREADS:\s*(\d+)\s+"
    r"NUM_TASKS:\s*(\d+)\s+"
    r"VEC_SIZE:\s*(\d+)"
)

TIME_FIELDS = [
    "time_wall_clock_unit",
    "time_wall_clock_mean",
    "time_wall_clock_stddev",
    "time_wall_clock_median",
    "time_wall_clock_min",
    "time_wall_clock_max",
    "time_wall_clock_iqr",
]

MEMORY_FIELDS = [
    "memory_peak_resident_unit",
    "memory_peak_resident_mean",
    "memory_peak_resident_stddev",
    "memory_peak_resident_median",
    "memory_peak_resident_min",
    "memory_peak_resident_max",
    "memory_peak_resident_iqr",
]

OUTPUT_FIELDS = [
    "executable",
    "num_threads",
    "num_tasks",
    "vec_size",
    *TIME_FIELDS,
    *MEMORY_FIELDS,
]


def parse_file(input_path):
    results = {
        "ctor_dtor": [],
        "vector_add": [],
    }

    config = None
    section = None

    with input_path.open("r", newline="", encoding="utf-8-sig") as file:
        for line_number, line in enumerate(file, start=1):
            line = line.strip()

            if not line:
                continue

            # Each configuration applies to subsequent benchmark rows.
            match = CONFIG_RE.search(line)
            if match:
                config = {
                    "num_threads": int(match.group(1)),
                    "num_tasks": int(match.group(2)),
                    "vec_size": int(match.group(3)),
                }
                continue

            if line == "CTOR DTOR":
                section = "ctor_dtor"
                continue

            if line == "VECTOR ADD":
                section = "vector_add"
                continue

            if line.startswith("BENCHMARKS COMPLETE"):
                section = None
                continue

            if section is None or config is None:
                continue

            # Parse benchmark data rows; ignore CSV headers and build output.
            try:
                row = next(csv.reader([line]))
            except csv.Error:
                continue

            if len(row) < 31 or not row[0].startswith("build/"):
                continue

            executable = row[0].rstrip("/").split("/")[-1]

            record = {
                "executable": executable,
                **config,
            }

            for field, value in zip(TIME_FIELDS, row[1:7]):
                record[field] = value

            for field, value in zip(MEMORY_FIELDS, row[7:13]):
                record[field] = value

            results[section].append(record)

    return results


def percentile(values, p):
    values = sorted(values)

    if not values:
        raise ValueError("Cannot calculate percentile of empty data")

    index = (len(values) - 1) * p
    lower = math.floor(index)
    upper = math.ceil(index)

    if lower == upper:
        return values[lower]

    fraction = index - lower
    return values[lower] * (1 - fraction) + values[upper] * fraction


def calculate_iqr(values):
    return percentile(values, 0.75) - percentile(values, 0.25)


def parse_json_measurements(input_path):
    text = input_path.read_text(encoding="utf-8-sig")
    decoder = json.JSONDecoder()

    # Find every top-level Hyperfine JSON object in the log.
    json_starts = re.finditer(
        r'(?m)^\{\s*"schema_version"\s*:',
        text,
    )

    results = {}

    for match in json_starts:
        data, _ = decoder.raw_decode(text, match.start())

        for benchmark in data["results"]:
            command = benchmark["command"]
            measurements = benchmark["measurements"]

            metrics = {}

            for metric in ("time_wall_clock", "memory_peak_resident"):
                values = [
                    measurement[metric]["value"]
                    for measurement in measurements
                    if metric in measurement
                    and "value" in measurement[metric]
                ]

                metrics[f"{metric}_iqr"] = (
                    calculate_iqr(values) if values else ""
                )

            results[command] = metrics

    if not results:
        raise ValueError("No appended Hyperfine JSON objects found")

    return results


def write_csv(path, records):
    with path.open("w", newline="", encoding="utf-8") as file:
        writer = csv.DictWriter(file, fieldnames=OUTPUT_FIELDS)
        writer.writeheader()
        writer.writerows(records)


def main():
    parser = argparse.ArgumentParser(
        description="Parse thread-pool benchmark logs into CSV files."
    )
    parser.add_argument("input", type=Path, help="Path to the .txt log file")
    parser.add_argument(
        "-o", "--out-dir",
        type=Path,
        help="Output directory (default: directory containing the input file)",
    )
    args = parser.parse_args()

    if not args.input.is_file():
        parser.error(f"Input file does not exist: {args.input}")

    output_dir = args.out_dir or args.input.parent
    output_dir.mkdir(parents=True, exist_ok=True)

    results = parse_file(args.input)

    iqr_results = parse_json_measurements(args.input)

    for records in results.values():
        for record in records:
            command = next(
                (
                    command
                    for command in iqr_results
                    if command.rstrip("/").split("/")[-1]
                    == record["executable"]
                ),
                None,
            )

            if command is not None:
                record.update(iqr_results[command])

    for section, records in results.items():
        output_path = output_dir / f"{section}.csv"
        write_csv(output_path, records)
        print(f"{output_path}: {len(records)} benchmark rows")


if __name__ == "__main__":
    main()
